\draw[black,thick] plot[domain=-3.8:3.8,samples=100,variable=\x] ({\x},{2.5*exp(-\x*\x/2)});
\draw[black,->] (-4,0) -- (4.3,0);
\draw[black] (-1,0) -- (-1,-0.12);
\draw[black] (0,0) -- (0,-0.12);
\draw[black] (2,0) -- (2,-0.12);
\path (-1,-0.12) node[below] {$78$} (0,-0.12) node[below] {$80$} (2,-0.12) node[below] {$84$} (4.3,0) node[right] {$\bar{x}$};
\path (0.4,1.2) node {$\approx0.815$};
\end{tikzpicture}
